+      box-shadow: var(--shadow);
+      backdrop-filter: blur(18px);
+    }
+
+    .eyebrow {
+      display: inline-flex;
+      align-items: center;
+      margin: 0 0 14px;
+      padding: 6px 12px;
+      border-radius: 999px;
+      color: var(--primary-dark);
+      background: rgba(40, 105, 255, 0.1);
+      font-size: 0.78rem;
+      font-weight: 700;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 6vw, 3rem);
+      line-height: 1.05;
+      letter-spacing: -0.055em;
+    }
+
+    .intro {
+      margin: 16px 0 30px;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.65;
+    }
+
+    .contact-form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 8px;
+    }
+
+    label {
+      color: #25314a;
+      font-size: 0.92rem;
+      font-weight: 700;
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid var(--line);
+      border-radius: 16px;
+      padding: 15px 16px;
+      color: var(--text);
+      background: #fbfdff;
+      font: inherit;
+      outline: none;
+      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
+    }
+
+    input::placeholder {
+      color: #98a4b7;
+    }
+
+    input:focus {
+      border-color: var(--primary);
+      background: #ffffff;
+      box-shadow: 0 0 0 4px var(--ring);
+    }
+
+    .helper-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.86rem;
+      line-height: 1.45;
+    }
+
+    .submit-button {
+      display: inline-flex;
+      justify-content: center;
+      align-items: center;
+      min-height: 52px;
+      margin-top: 4px;
+      border: 0;
+      border-radius: 16px;
+      padding: 0 22px;
+      color: #ffffff;
+      background: linear-gradient(135deg, var(--primary), #6f55ff);
+      box-shadow: 0 12px 26px rgba(40, 105, 255, 0.28);
+      font: inherit;
+      font-weight: 800;
+      cursor: pointer;
+      transition: transform 160ms ease, box-shadow 160ms ease;
+    }
+
+    .submit-button:hover {
+      transform: translateY(-1px);
+      box-shadow: 0 16px 32px rgba(40, 105, 255, 0.34);
+    }
+
+    .submit-button:focus-visible {
+      outline: 4px solid var(--ring);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 560px) {
+      .support-card {
+        padding: 28px;
+        border-radius: 22px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main id="root"></main>
+
+  <script>
+    function Field({ id, label, type = "text", placeholder, required = false, helperText, autocomplete, inputmode }) {
+      return `
+        <div class="form-field">
+          <label for="${id}">${label}${required ? " *" : ""}</label>
+          <input
+            id="${id}"
+            name="${id}"
+            type="${type}"
+            placeholder="${placeholder}"
+            autocomplete="${autocomplete}"
+            ${inputmode ? `inputmode="${inputmode}"` : ""}
+            ${required ? "required" : ""}
+          >
+          ${helperText ? `<p class="helper-text" id="${id}-helper">${helperText}</p>` : ""}
+        </div>
+      `;
+    }
+
+    function ContactForm() {
+      return `
+        <form class="contact-form" action="#" method="post" novalidate>
+          ${Field({
+            id: "full-name",
+            label: "Full name",
+            placeholder: "Alex Morgan",
+            required: true,
+            autocomplete: "name"
+          })}
+          ${Field({
+            id: "email-address",
+            label: "Email address",
+            type: "email",
+            placeholder: "alex@example.com",
+            required: true,
+            autocomplete: "email",
+            inputmode: "email"
+          })}
+          ${Field({
+            id: "phone-number",
+            label: "Phone number",
+            type: "tel",
+            placeholder: "(555) 123-4567",
+            autocomplete: "tel",
+            inputmode: "tel",
+            helperText: "Optional. Use a country code if outside the US, for example +1 555 123 4567."
+          })}
+          <button class="submit-button" type="submit">Contact support</button>
+        </form>
+      `;
+    }
+
+    function SupportPage() {
+      return `
+        <section class="page-shell" aria-labelledby="support-title">
+          <div class="support-card">
+            <p class="eyebrow">Support request</p>
+            <h1 id="support-title">How can we help?</h1>
+            <p class="intro">
+              Tell us who to contact and our support team will follow up with next steps.
+            </p>
+            ${ContactForm()}
+          </div>
+        </section>
+      `;
+    }
+
+    document.getElementById("root").innerHTML = SupportPage();
+  </script>
+</body>
+</html>
*** End Patch
