       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(40, 105, 255, 0.16), transparent 34rem),
         linear-gradient(135deg, #f9fbff 0%, var(--bg) 100%);
     }

     .page-shell {
       display: grid;
       place-items: center;
       min-height: 100vh;
       padding: 48px 20px;
     }

