       border-radius: 28px;
       background: rgba(255, 255, 255, 0.9);
       box-shadow: var(--shadow);
       backdrop-filter: blur(18px);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       margin: 0 0 14px;
       padding: 6px 12px;
       border-radius: 999px;
       color: var(--primary-dark);
       background: rgba(40, 105, 255, 0.1);
