       line-height: 1.05;
       letter-spacing: -0.055em;
     }

     .intro {
       margin: 16px 0 30px;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.65;
     }

     .contact-form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

